window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-35701\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυξίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5383 na letra π · nº geral 35701</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 caixa de buxo para remédios ou substâncias diversas 2 tinteiro. 〈πύξος〉</p></section></article>\n<article id=\"entry-dgp-35702\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πύξος, ου (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5384 na letra π · nº geral 35702</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">buxo, arbusto.</p></section></article>\n<article id=\"entry-dgp-35703\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πύον</h1><div class=\"entry-meta\"><span>DGP · ordem 5385 na letra π · nº geral 35703</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e πῦον, ου (τό) 1 pus 2 colostro. 〈πύθω〉</p></section></article>\n<article id=\"entry-dgp-35704\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πῦος, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 5386 na letra π · nº geral 35704</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e πυός, οῦ (ὁ) colostro.</p></section></article>\n<article id=\"entry-dgp-35705\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πῦρ, πυρός</h1><div class=\"entry-meta\"><span>DGP · ordem 5387 na letra π · nº geral 35705</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pl. πυρά, dat. πυροῖς (τό) 1 fogo: νηυσὶ πῦρ ἐμβάλλειν hom. lançar fogo nos navios, expr. ἐν πυρὶ γε­νοίατο hom. que eles ardam no fogo, i.e., que sejam aniquilados, prov. μετὰ τινος διὰ πυρὸς ἰέναι xen. cruzar o fogo com alguém, i.e., partilhar com esse alguém todos os perigos, διὰ τοῦ πυρὸς ἐθέλω βαδίζειν ar. aceito caminhar pelo fogo, i.e., topo qualquer coisa (menos…), διὰ πυρὸς ἔρχεσθαι ou μολεῖν τινι eur. estar enfurecido contra alguém, εἰς πῦρ ξαίνειν plat. cardar a lã no fogo, i.e., trabalhar em vão 2 fogueira; pira: prov. φεύγων καπνὸν εἰς πῦρ ἐμπίπτει plat. ao fugir da fumaça cai dentro da fogueira, i.e., ao fugir de um mal depara com outro pior, εὶς πῦρ ἅλλεσθαι xen. pular na fogueira, i.e., não recuar diante de nenhum perigo 3 fogo de sacrifício 4 fogo do lar 5 fogo celeste; raio ou relâmpago 6 fogo solar 7 brilho dos astros 8 clarão de tochas, de archotes 9 fogo de acampamento 10 brilho dos olhos 11 febre 12 fogo, símbolo de força, de destruição ou de devastação 13 fogo da paixão; ardor amoroso.</p></section></article>\n<article id=\"entry-dgp-35706\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρά1, ῶν (τά)</h1><div class=\"entry-meta\"><span>DGP · ordem 5388 na letra π · nº geral 35706</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pl. de πῦρ.</p></section></article>\n<article id=\"entry-dgp-35707\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρά2, ᾶς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5389 na letra π · nº geral 35707</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pira; fogueira 2 altar para o sacrifício; ara 3 fogo que queima sobre esse altar 4 amontoado de matéria combustível 5 feixe de tochas. 〈πῦρ〉</p></section></article>\n<article id=\"entry-dgp-35708\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυράγρα, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5390 na letra π · nº geral 35708</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tenaz de ferreiro 2 Medic. fórceps. 〈πῦρ, ἀγρέω〉</p></section></article>\n<article id=\"entry-dgp-35709\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρακτέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 5391 na letra π · nº geral 35709</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só impf. ἐπυράκτεον) 1 deixar no fogo até incandecer; fazer ficar em brasa 2 dar têmpera a, ac. 〈πῦρ, ἀκτός〉</p></section></article>\n<article id=\"entry-dgp-35710\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρακτόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 5392 na letra π · nº geral 35710</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fazer queimar 2 pôr em brasa; fazer incandescer 3 temperar; dar têmpera a (flecha, dardo), ac. ♦ pas. 4 queimar 5 incandescer 6 ser ferido por uma flecha forjada no fogo. 〈πῦρ, ἀκτός〉</p></section></article>\n<article id=\"entry-dgp-35711\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυραμίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5393 na letra π · nº geral 35711</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pirâmide egípcia 2 Geom. pirâmide 3 bolo de mel e farinha.</p></section></article>\n<article id=\"entry-dgp-35712\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυραμοῦς, οῦντος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5394 na letra π · nº geral 35712</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 bolo de mel e farinha, prêmio para dançarinos 2 bolo da vitória, i.e., vitória. 〈πυρός〉</p></section></article>\n<article id=\"entry-dgp-35713\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυργηδόν</h1><div class=\"entry-meta\"><span>DGP · ordem 5395 na letra π · nº geral 35713</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. em forma de torre, i.e., em fileira cerrada. 〈πύργος, -δον〉</p></section></article>\n<article id=\"entry-dgp-35714\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυργηρέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 5396 na letra π · nº geral 35714</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 guardar as muralhas ♦ pas. 2 estar sitiado. 〈πύργος〉</p></section></article>\n<article id=\"entry-dgp-35715\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πύργινος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5397 na letra π · nº geral 35715</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que concerne às torres, à cidade. 〈πύργος〉</p></section></article>\n<article id=\"entry-dgp-35716\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυργίον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 5398 na letra π · nº geral 35716</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dim. de πύργος.</p></section></article>\n<article id=\"entry-dgp-35717\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυργοδάϊκτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5399 na letra π · nº geral 35717</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que destrói as torres. 〈πύργος, δαΐζω〉</p></section></article>\n<article id=\"entry-dgp-35718\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυργομαχέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 5400 na letra π · nº geral 35718</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 atacar ou defender uma torre 2 combater de uma torre ♦ pas. 3 ser atacado; ser sitiado. 〈πύργος, μάχομαι〉</p></section></article>\n<article id=\"entry-dgp-35719\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πύργος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5401 na letra π · nº geral 35719</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 torre 2 torre móvel para sitiar cidades 3 fortificação guarnecida de torres; cidadela 4 fileira cerrada de tropas 5 baluarte; defesa; defensor (pessoa) 6 qualquer construção em formato de torre 7 andar superior da casa reservado às mulheres; gineceu 8 copo de dados.</p></section></article>\n<article id=\"entry-dgp-35720\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυργοφορέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 5402 na letra π · nº geral 35720</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">carregar uma torre. 〈πυργοφόρος〉</p></section></article>\n<article id=\"entry-dgp-35721\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυργοφόρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5403 na letra π · nº geral 35721</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que carrega uma torre (elefante). 〈πύργος, φέρω〉</p></section></article>\n<article id=\"entry-dgp-35722\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυργοφύλαξ, ακος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5404 na letra π · nº geral 35722</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">sentinela de uma torre.</p></section></article>\n<article id=\"entry-dgp-35723\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυργόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 5405 na letra π · nº geral 35723</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fortificar ou munir com torres, ac. 2 proteger; defender 3 construir, erguer como uma torre: π. ῥήματα σεμνά ar. construir palavras imponentes como torres 4 dar muita importância a; valorizar muito 5 exaltar; magnificar; vangloriar: τὰ μὲν πυργοῦσ’ ἄνω τὸ μηδὲν ὄντα eur. elevam ao alto o que não tem valor ♦ méd. 6 munir de torres para si, gen. 7 exaltar; magnificar 8 orgulhar-se; envaidecer-se de, dat. 〈πύργος〉</p></section></article>\n<article id=\"entry-dgp-35724\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυργώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 5406 na letra π · nº geral 35724</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que se ergue como uma torre. 〈πύργος, -ωδης〉</p></section></article>\n<article id=\"entry-dgp-35725\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πύργωμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 5407 na letra π · nº geral 35725</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cidade amuralhada 2 pl. muralhas com torres. 〈πυργόω〉</p></section></article>\n<article id=\"entry-dgp-35726\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυργῶτις, ιδος</h1><div class=\"entry-meta\"><span>DGP · ordem 5408 na letra π · nº geral 35726</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) construída em forma de torre; semelhante a uma torre. 〈πυργόω〉</p></section></article>\n<article id=\"entry-dgp-35727\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρδαής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 5409 na letra π · nº geral 35727</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que destrói pelo fogo. 〈πῦρ, δαίω〉</p></section></article>\n<article id=\"entry-dgp-35728\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρεῖον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 5410 na letra π · nº geral 35728</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ger. pl., o que serve para acender o fogo 2 pl. pedaços de madeira que, friccionados um contra o outro, produzem o fogo. 〈πῦρ〉</p></section></article>\n<article id=\"entry-dgp-35729\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρέσσω,</h1><div class=\"entry-meta\"><span>DGP · ordem 5411 na letra π · nº geral 35729</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. -έττω (impf. ἐπύρεσσον, fut. πυρέξω, aor. ἐπύρεξα, perf. πεπύρεχα; perf. pas. πεπύρεγμαι) ter febre. 〈πυρετός〉</p></section></article>\n<article id=\"entry-dgp-35730\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρετός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5412 na letra π · nº geral 35730</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 calor ardente 2 febre. 〈πῦρ〉</p></section></article>\n<article id=\"entry-dgp-35731\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρή</h1><div class=\"entry-meta\"><span>DGP · ordem 5413 na letra π · nº geral 35731</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = πυρά2.</p></section></article>\n<article id=\"entry-dgp-35732\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρήν, ῆνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5414 na letra π · nº geral 35732</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 caroço, semente ou grão de fruta 2 grão de incenso 3 baga de sabugueiro 4 Medic. ponta arredondada de sonda cirúrgica 5 tipo de pedra preciosa.</p></section></article>\n<article id=\"entry-dgp-35733\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρηφόρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5415 na letra π · nº geral 35733</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">πυροφόρος.</p></section></article>\n<article id=\"entry-dgp-35734\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5416 na letra π · nº geral 35734</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 transpiração provocada pelo calor de uma estufa ou de banho de vapor 2 calor de estufa 3 estufa 4 pesca com tocha. 〈πῦρ〉</p></section></article>\n<article id=\"entry-dgp-35735\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυριάτη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5417 na letra π · nº geral 35735</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">primeiro leite (de vaca, de cabra) coalhado em lenta cocção e servido quente. 〈πῦρ〉</p></section></article>\n<article id=\"entry-dgp-35736\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυριατήριον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 5418 na letra π · nº geral 35736</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">sauna. 〈πῦρ〉</p></section></article>\n<article id=\"entry-dgp-35737\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυριγενέτας, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 5419 na letra π · nº geral 35737</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) dór. = πυριγενής.</p></section></article>\n<article id=\"entry-dgp-35738\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυριγενής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 5420 na letra π · nº geral 35738</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 nascido do fogo ou no fogo 2 trabalhado ou forjado no fogo. 〈πῦρ, γίγνομαι〉</p></section></article>\n<article id=\"entry-dgp-35739\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρίγονος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5421 na letra π · nº geral 35739</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">nascido do fogo ou no fogo. 〈πῦρ, γίγνομαι〉</p></section></article>\n<article id=\"entry-dgp-35740\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρίδαπτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5422 na letra π · nº geral 35740</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">consumido, devorado pelo fogo. 〈πῦρ, δάπτω〉</p></section></article>\n<article id=\"entry-dgp-35741\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρίδιον1, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 5423 na letra π · nº geral 35741</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">foguinho; faísca. 〈πῦρ〉</p></section></article>\n<article id=\"entry-dgp-35742\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρίδιον2, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 5424 na letra π · nº geral 35742</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dim. de πυρός.</p></section></article>\n<article id=\"entry-dgp-35743\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυριήκης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 5425 na letra π · nº geral 35743</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">com a ponta em brasa. 〈πῦρ, ἀκή〉</p></section></article>\n<article id=\"entry-dgp-35744\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρίκαυστος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5426 na letra π · nº geral 35744</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 queimado no ou pelo fogo 2 causado por queimadura ♦ τὸ πυρίκαυστον 3 emplastro para queimadura 4 pl. feridas de queimadura. 〈πῦρ, καίω〉</p></section></article>\n<article id=\"entry-dgp-35745\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρίκαυτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5427 na letra π · nº geral 35745</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 inflamatório (doença) 2 que apresenta inflamação; inflamado (ferida) 3 incendiado. 〈πῦρ, καίω〉</p></section></article>\n<article id=\"entry-dgp-35746\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυριλαμπής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 5428 na letra π · nº geral 35746</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que brilha como fogo. 〈πῦρ, λάμπω〉</p></section></article>\n<article id=\"entry-dgp-35747\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυριμανέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 5429 na letra π · nº geral 35747</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">espalhar-se em chamas violentas. 〈πῦρ, μαίνομαι〉</p></section></article>\n<article id=\"entry-dgp-35748\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πύρινος1, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5430 na letra π · nº geral 35748</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de fogo; inflamado; ardente 2 violento ou quente como fogo. 〈πῦρ〉</p></section></article>\n<article id=\"entry-dgp-35749\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πύρινος2, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5431 na letra π · nº geral 35749</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de trigo; de frumento. 〈πυρός〉</p></section></article>\n<article id=\"entry-dgp-35750\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρίτης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 5432 na letra π · nº geral 35750</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) 1 de fogo ♦ ὁ πυρίτης 2 ferreiro 3 pirita, pedra 4 tipo de pedra preciosa. 〈πῦρ〉</p></section></article>\n<article id=\"entry-dgp-35751\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυριφλεγέθων</h1><div class=\"entry-meta\"><span>DGP · ordem 5433 na letra π · nº geral 35751</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.), -θον (n.), gen. οντος 1 com chamas ardentes; flamejante ♦ ὁ Πυριφλεγέθων 2 Perifle­getonte, rio dos infernos. 〈πῦρ, φλεγέθω〉</p></section></article>\n<article id=\"entry-dgp-35752\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυριφλεγής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 5434 na letra π · nº geral 35752</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que queima com a chama; flamejante 2 Medic. muito inflamado 3 causado por inflamação. 〈πῦρ, φλέγω〉</p></section></article>\n<article id=\"entry-dgp-35753\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρίχρως, ωτος,</h1><div class=\"entry-meta\"><span>DGP · ordem 5435 na letra π · nº geral 35753</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. -ων (masc., fem.) da cor do fogo. 〈πῦρ, χρώς〉</p></section></article>\n<article id=\"entry-dgp-35754\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρκαϊά</h1><div class=\"entry-meta\"><span>DGP · ordem 5436 na letra π · nº geral 35754</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e πυρκαιά, ᾶς (ἡ) 1 pira; fogueira 2 incêndio 3 chama (de amor) 4 ruínas de incêndio 5 oliveira selvagem nascida de troncos semi-queimados. 〈πῦρ, καίω〉</p></section></article>\n<article id=\"entry-dgp-35755\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρκόοι, ων (οἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5437 na letra π · nº geral 35755</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adivinhos de Delfos que prediziam o futuro pelo exame das vísceras no fogo. 〈πῦρ, κοέω〉</p></section></article>\n<article id=\"entry-dgp-35756\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρνόν, οῦ (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 5438 na letra π · nº geral 35756</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pão de frumento 2 cibo; alimento. 〈πύρινος2〉</p></section></article>\n<article id=\"entry-dgp-35757\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυροβόλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5439 na letra π · nº geral 35757</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que lança fogo ♦ οἱ πυροβόλοι e τὰ πυροβόλα 2 máquina bélica para lançar projéteis incendiários. 〈πῦρ, βάλλω〉</p></section></article>\n<article id=\"entry-dgp-35758\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυροειδής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 5440 na letra π · nº geral 35758</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">semelhante ao fogo. 〈πῦρ, εἶδος〉</p></section></article>\n<article id=\"entry-dgp-35759\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυροειδῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 5441 na letra π · nº geral 35759</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. como fogo.</p></section></article>\n<article id=\"entry-dgp-35760\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυροῖς</h1><div class=\"entry-meta\"><span>DGP · ordem 5442 na letra π · nº geral 35760</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. πῦρ.</p></section></article>\n<article id=\"entry-dgp-35761\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρός1</h1><div class=\"entry-meta\"><span>DGP · ordem 5443 na letra π · nº geral 35761</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. de πῦρ.</p></section></article>\n<article id=\"entry-dgp-35762\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρός2, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5444 na letra π · nº geral 35762</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 trigo; frumento 2 grão de trigo.</p></section></article>\n<article id=\"entry-dgp-35763\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυροφόρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5445 na letra π · nº geral 35763</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que produz trigo; fértil em trigo 2 que transporta trigo. 〈πυρός, φέρω〉</p></section></article>\n<article id=\"entry-dgp-35764\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 5446 na letra π · nº geral 35764</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pôr fogo em; consumir pelo fogo; queimar, gen. 2 produzir fogo 3 purificar pelo fogo 4 consumir de paixão; inflamar; abrasar ♦ méd. 5 colocar na pira funerária alguém dos seus ♦ pas. 6 ser consumido pelo fogo 7 pegar fogo; incendiar-se 8 fundir-se sob a ação do fogo 9 (ouro) ser provado pelo fogo 10 estar inflamado, arder de paixão por alguém, dat. 〈πῦρ〉</p></section></article>\n<article id=\"entry-dgp-35765\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πύρπνοος-ους, οος-ους, οον-ουν</h1><div class=\"entry-meta\"><span>DGP · ordem 5447 na letra π · nº geral 35765</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que sopra ou respira fogo 2 inflamado; ardente. 〈πῦρ, πνέω〉</p></section></article>\n<article id=\"entry-dgp-35766\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρπολέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 5448 na letra π · nº geral 35766</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 manter-se perto do fogo 2 atiçar, manter o fogo 3 destruir pelo fogo; incendiar, ac. 4 consumir; inflamar (de dor, de amor) ♦ méd. 5 consumir.</p></section></article>\n<article id=\"entry-dgp-35767\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πύρρα, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5449 na letra π · nº geral 35767</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 espécie de pássaro vermelho ♦ ἡ Πύρρα 2 Pirra, n. da filha de Pandora e de uma cidade de Lesbos. 〈πυρρός〉</p></section></article>\n<article id=\"entry-dgp-35768\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρράζω</h1><div class=\"entry-meta\"><span>DGP · ordem 5450 na letra π · nº geral 35768</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. ser da cor do fogo, vermelho, rubro. 〈πυρρός〉</p></section></article>\n<article id=\"entry-dgp-35769\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρρίχη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5451 na letra π · nº geral 35769</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pírrica, dança de guerra: πυρρίχην βλέπειν ar. ter olhar belicoso 2 pl. contorções. 〈Πύρριχος〉</p></section></article>\n<article id=\"entry-dgp-35770\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρριχίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 5452 na letra π · nº geral 35770</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dançar a pírrica. 〈πυρρίχη〉</p></section></article>\n<article id=\"entry-dgp-35771\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρρίχιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5453 na letra π · nº geral 35771</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 da dança pírrica ♦ ὁ πυρρίχιος 2 Métr. pirríquio, pé de duas sílabas breves. 〈πυρρίχη〉</p></section></article>\n<article id=\"entry-dgp-35772\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πύρριχος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5454 na letra π · nº geral 35772</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Pírrico, n. de h., partic. do criador da dança pírrica.</p></section></article>\n<article id=\"entry-dgp-35773\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρρόθριξ, -τριχος</h1><div class=\"entry-meta\"><span>DGP · ordem 5455 na letra π · nº geral 35773</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) de cabelos ruivos. 〈πυρ­ρός, θρίξ〉</p></section></article>\n<article id=\"entry-dgp-35774\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρρός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 5456 na letra π · nº geral 35774</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 da cor do fogo; rubro 2 de cabelos ruivos 3 de pelo fulvo (animal) 4 ruborizado ♦ τὸ πυρρόν 5 a cor vermelha. 〈πῦρ〉</p></section></article>\n<article id=\"entry-dgp-35775\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πύρρος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5457 na letra π · nº geral 35775</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Pirro, n. de h., partic. do filho e do neto de Aquiles.</p></section></article>\n<article id=\"entry-dgp-35776\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρρόχροος-ους, οος-ους, οον-ουν</h1><div class=\"entry-meta\"><span>DGP · ordem 5458 na letra π · nº geral 35776</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de cor ruça. 〈πυρ­ρός, χρόα〉</p></section></article>\n<article id=\"entry-dgp-35777\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρρόχρως, ως, ων</h1><div class=\"entry-meta\"><span>DGP · ordem 5459 na letra π · nº geral 35777</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ruço.</p></section></article>\n<article id=\"entry-dgp-35778\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρσεία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5460 na letra π · nº geral 35778</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">sinalização pelo fogo: ἀποδιδόναι τὴν πυρσείαν ἀλλήλοις pol. trocar sinais entre si por meio do fogo. 〈πυρσεύω〉</p></section></article>\n<article id=\"entry-dgp-35779\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρσεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 5461 na letra π · nº geral 35779</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 dar sinais pelo fogo 2 dar um sinal; anunciar 3 fazer brilhar 4 pôr fogo a; acender (o ódio) 5 queimar algo ♦ pas. 6 ser indicado ou anunciado por sinais de fogo 7 brilhar; resplender. 〈πυρσός〉</p></section></article>\n<article id=\"entry-dgp-35780\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρσός1, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5462 na letra π · nº geral 35780</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 facho iluminado; tocha 2 archote aceso para dar sinal; sinal de fogo 3 ger. pl., fogo 4 pl. fogo de acampamento. 〈πῦρ〉</p></section></article>\n<article id=\"entry-dgp-35781\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρσός2</h1><div class=\"entry-meta\"><span>DGP · ordem 5463 na letra π · nº geral 35781</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">poét. = πυρρός.</p></section></article>\n<article id=\"entry-dgp-35782\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρφορέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 5464 na letra π · nº geral 35782</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 carregar o fogo (tocha, archote) 2 pôr fogo em; queimar, ac. 〈πυρφόρος〉</p></section></article>\n<article id=\"entry-dgp-35783\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρφόρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5465 na letra π · nº geral 35783</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que traz ou lança fogo, epít. de divindades, do sol, do raio 2 que traz a febre, a doença, a peste 3 que abrasa de amor ♦ ὁ πυρφόρος 4 sacerdote que acompanhava o exército lacedemônio com o fogo sagrado 5 sacerdote sírio 6 máquina de lançar projéteis inflamados. 〈πῦρ, φέρω〉</p></section></article>\n<article id=\"entry-dgp-35784\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 5466 na letra π · nº geral 35784</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 abrasador; ardente 2 vermelho como fogo 3 Medic. seguido de inflamação ♦ τὸ πυρῶδες 4 substância de fogo 5 natureza ardente. 〈πῦρ, -ωδης〉</p></section></article>\n<article id=\"entry-dgp-35785\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρωπός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 5467 na letra π · nº geral 35785</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 da cor de fogo ♦ τὸ πυρωπός 2 a cor vermelho-fogo. 〈πῦρ, ὤψ〉</p></section></article>\n<article id=\"entry-dgp-35786\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πύρωσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5468 na letra π · nº geral 35786</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 combustão 2 Medic. inflamação; febre 3 ação de cozinhar 4 ação de ferver 5 calor; ardor. 〈πυρόω〉</p></section></article>\n<article id=\"entry-dgp-35787\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πύσμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 5469 na letra π · nº geral 35787</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 interrogação 2 Gram. partícula interrogativa. 〈πυνθάνομαι〉</p></section></article>\n<article id=\"entry-dgp-35788\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυστιάομαι-ῶμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 5470 na letra π · nº geral 35788</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">interrogar; perguntar. 〈πύστις〉</p></section></article>\n<article id=\"entry-dgp-35789\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πύστις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5471 na letra π · nº geral 35789</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pergunta; interrogação 2 informação 3 notícia 4 renome; fama.</p></section></article>\n<article id=\"entry-dgp-35790\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυτία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5472 na letra π · nº geral 35790</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 colostro de fêmea animal 2 coalho 3 espécie de bolo. 〈πύος〉</p></section></article>\n<article id=\"entry-dgp-35791\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 5473 na letra π · nº geral 35791</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">como pus; purulento. 〈πῦον, -ωδης〉</p></section></article>\n<article id=\"entry-dgp-35792\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πῶ,</h1><div class=\"entry-meta\"><span>DGP · ordem 5474 na letra π · nº geral 35792</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. κῶ adv. encl. 1 ainda; de alguma maneira, após neg. com a qual πῶ ger. se funde numa só palavra: οὔπω, μήπω ainda não, οὐδέπω, μηδέπω, οὐπώποτε, μηπώποτε, οὐδεπώποτε, μηδεπώποτε jamais, οὐδείς πω, οὐδεμία πω, οὐδέν πω nenhum ainda, nenhuma ainda, nada ainda, ἔγνω ὅτι οὐδέν πω ἐνδώσουσιν tuc. compreendeu que não cederiam em nada ainda, οὔ ou μή τί πω ainda não de modo algum, οὔκω πρίν her., οὔπω ὄφρα hom. não antes que 2 nunca; jamais, em or. inter. que pressupõe resposta neg.: πόλις ἀφισταμένη τίς πω…; tuc. qual cidade em revolta nunca…? 3 não importa como; de uma maneira qualquer: οὔπω, μήπω de nenhuma maneira, de modo algum.</p></section></article>\n<article id=\"entry-dgp-35793\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πώγων, ωνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5475 na letra π · nº geral 35793</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 barba 2 barba de animal, de peixe, de planta 3 língua (de fogo).</p></section></article>\n<article id=\"entry-dgp-35794\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πωγωνίας, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 5476 na letra π · nº geral 35794</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) barbudo: π. ἀστήρ artt. astro barbudo, ref. a um tipo de cometa. 〈πώγων〉</p></section></article>\n<article id=\"entry-dgp-35795\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πωγώνιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 5477 na letra π · nº geral 35795</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dim. de πώγων.</p></section></article>\n<article id=\"entry-dgp-35796\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πωγωνοτροφέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 5478 na letra π · nº geral 35796</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">conservar ou deixar crescer a barba. 〈πώγων, τρέφω〉</p></section></article>\n<article id=\"entry-dgp-35797\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πωγωνοτροφία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5479 na letra π · nº geral 35797</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">hábito de deixar crescer a barba. 〈πώγων, τρέφω〉</p></section></article>\n<article id=\"entry-dgp-35798\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πώεα</h1><div class=\"entry-meta\"><span>DGP · ordem 5480 na letra π · nº geral 35798</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. πῶϋ.</p></section></article>\n<article id=\"entry-dgp-35799\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πώλε’ πώλεο</h1><div class=\"entry-meta\"><span>DGP · ordem 5481 na letra π · nº geral 35799</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">em elisão.</p></section></article>\n<article id=\"entry-dgp-35800\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πωλέεσκε</h1><div class=\"entry-meta\"><span>DGP · ordem 5482 na letra π · nº geral 35800</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. impf. iter. de πωλέω.</p></section></article>\n";
